# Original 26_figs_all.R lipid PCA logic, rendered without plot titles/subtitles.
suppressPackageStartupMessages({library(vroom);library(dplyr);library(stringr);library(ggplot2);library(patchwork)})
root <- '/Users/nirwantandukar/Documents/Github/SoLD_paper';out <- '/Users/nirwantandukar/Documents/Github/SAP-Lipidomics-Database/fig/new_figures/SuppFig_Lipid_PCA.png'; cols<-c(PC='#00441B',PA='#1B7837',PE='#41AB5D',LPC='#66C2A4',LPE='#2CA25F',PG='#78C679',PS='#C2E699',DG='#54278F',DGDG='#F768A1',MG='#8941ED',MGDG='#FBB4D9',SQDG='#9D4D6C',TG='#ED804A');get_class<-function(x){z<-str_extract(x,'^[A-Za-z0-9]+(?=\\()');ifelse(z %in% names(cols),z,'Other')};grp<-function(x)case_when(x%in%c('PC','PA','PE','LPC','LPE','PG','PS')~'Phospholipids',x%in%c('MGDG','DGDG','SQDG')~'Glycolipids',x%in%c('DG','MG')~'Neutral',x=='TG'~'Storage',TRUE~'Other');read_x<-function(p,c){vroom(p,show_col_types=FALSE)|>select(-c(2,3,4))|>rename(Compound_Name=1)|>mutate(Condition=c)};ctl<-read_x(file.path(root,'data/SPATS_fitted/non_normalized_intensities/Final_subset_control_all_lipids_fitted_phenotype_non_normalized.csv'),'Control');lin<-read_x(file.path(root,'data/SPATS_fitted/non_normalized_intensities/Final_subset_lowinput_all_lipids_fitted_phenotype_non_normalized.csv'),'LowInput');sub<-function(d){x<-names(d)[grepl('\\(',names(d))];pat<-paste0('^(',paste(names(cols),collapse='|'),')\\(');d|>select(Compound_Name,Condition,all_of(x[grepl(pat,x)]))};tic<-function(d){m<-as.matrix(d|>select(-Compound_Name,-Condition));rs<-rowSums(m);bind_cols(d|>select(Compound_Name,Condition),as.data.frame(sweep(m,1,rs,'/')*100))};a<-tic(sub(ctl));b<-tic(sub(lin));shared<-intersect(names(a),names(b));a<-a|>select(all_of(shared));b<-b|>select(all_of(shared));run<-function(d){X<-as.matrix(d|>select(-Compound_Name,-Condition));P<-X/pmax(rowSums(X),1e-12)+1e-6;P<-P/rowSums(P);L<-log(P);V<-t(L-rowMeans(L));V<-t(scale(t(V)));V[is.na(V)]<-0;p<-prcomp(V,center=FALSE,scale.=FALSE);z<-as.data.frame(p$x[,1:2]);names(z)<-c('PC1','PC2');z$Lipid<-rownames(p$x);z$Class<-get_class(z$Lipid);z$Group<-grp(z$Class);attr(z,'pve')<-(p$sdev^2/sum(p$sdev^2))[1:2];z};plotp<-function(z,legend){v<-attr(z,'pve');ggplot(z,aes(PC1,PC2,color=Class))+geom_point(size=2.5,alpha=.8)+stat_ellipse(aes(group=Group,color=NULL),linetype='dashed',linewidth=.8,color='grey50',level=.95,type='norm')+scale_color_manual(values=cols)+labs(x=sprintf('PC1 (%.1f%%)',100*v[1]),y=sprintf('PC2 (%.1f%%)',100*v[2]))+theme_minimal(base_size=12)+theme(axis.text=element_text(color='black',size=12),axis.title=element_text(face='bold',size=14),legend.position=if(legend)'right' else 'none',axis.line=element_line(color='black',linewidth=.5))};fig<-(plotp(run(a),FALSE)+plotp(run(b),TRUE)+plot_layout(guides='collect')&theme(legend.position='bottom'))+plot_annotation(tag_levels='A',theme=theme(plot.tag=element_text(face='bold',size=16)));dir.create(dirname(out),recursive=TRUE,showWarnings=FALSE);ggsave(out,fig,width=14,height=7,units='in',dpi=300,bg='white')
